// helpers
const inp = $input.first().json;
const empty = v => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);
const pick = (keys) => { const o = {}; for (const k of keys) if (!empty(inp[k])) o[k] = inp[k]; return o; };
const asObj = (v) => { if (empty(v)) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { throw new Error('EFX E_VALIDATION: JSON field is not valid JSON'); } } return v; };
const asArr = (v) => empty(v) ? [] : (Array.isArray(v) ? v : String(v).split(',').map(s => s.trim()).filter(Boolean));
const bool = (v, d) => empty(v) ? d : (v === true || String(v).toLowerCase() === 'true');
const passthru = { actor: empty(inp.actor) ? undefined : inp.actor, idempotencyKey: empty(inp.idempotencyKey) ? '' : String(inp.idempotencyKey) };

const p = {};
if (!empty(inp.taskId)) p.taskId = String(inp.taskId).trim();
if (!empty(inp.workflowId)) p.workflowId = String(inp.workflowId).trim();
if (!empty(inp.formType)) p.formType = String(inp.formType).trim();
if (!p.taskId && !(p.workflowId && p.formType)) throw new Error('EFX E_VALIDATION: taskId, or workflowId + formType, is required');
if (!empty(inp.notes)) p.notes = String(inp.notes);
const checklist = asObj(inp.checklist); if (Object.keys(checklist).length) p.checklist = checklist;
const formData = asObj(inp.formData); if (Object.keys(formData).length) p.formData = formData;
if (bool(inp.dryRun, false)) p.dryRun = true;
return [{ json: Object.assign({ fn: 'n8n_closeTask', args: [p], treatAlreadyClosedAsSuccess: bool(inp.treatAlreadyClosedAsSuccess, true) }, passthru) }];
